action.command:
cd /workspace && grep -a -oiE '<title>[^<]*</title>' /tmp/root.html | head -1; grep -a -o 'sva-studio\|SVA Studio' /tmp/root.html | sort | uniq -c | head; echo "=== final doctor run ==="; timeout 300 pnpm env:doctor:local-builder --json >/tmp/doctor3.json 2>/dev/null
node -e "
const fs=require('fs');
let raw=fs.readFileSync('/tmp/doctor3.json','utf8');
let depth=0, end=0, started=false;
for(let i=0;i<raw.length;i++){const c=raw[i]; if(c==='{')depth++; if(c==='}'){depth--; if(started&&depth===0){end=i+1;break;}} if(c==='{')started=true;}
const j=JSON.parse(raw.slice(0,end));
console.log('DOCTOR PROFILE:', j.profile, '| STATUS:', j.status);
for(const c of j.checks){
  console.log('  '+String(c.name).padEnd(36), String(c.status).padEnd(8), c.code||'');
}
"

